from pathlib import Path
p = Path('/home/ubuntu/labrkp-workforce/client/src/pages/WorkerSignup.tsx')
s = p.read_text()
s = s.replace('const [form, setForm] = useState({ name: "", phone: "", email: "", gender: "Male", city: "Peshawar", skill: "Electrical", experience: "", bio: "", consent: false });', 'const [form, setForm] = useState({ name: "", phone: "", email: "", gender: "Male", city: "Peshawar", skill: "Electrical", experience: "", bio: "", consent: false, diplomaProof: null as { name: string; type: string; data: string } | null, skillProof: null as { name: string; type: string; data: string } | null });')
s = s.replace('const update = (key: keyof typeof form, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }));', 'const update = (key: keyof typeof form, value: string | boolean | { name: string; type: string; data: string } | null) => setForm((current) => ({ ...current, [key]: value }));\n  const readProof = (key: "diplomaProof" | "skillProof", file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => update(key, { name: file.name, type: file.type, data: String(reader.result) }); reader.readAsDataURL(file); };')
s = s.replace('body: JSON.stringify(form)', 'body: JSON.stringify(form)')
old = '<button type="button" className="mt-4 flex w-full items-center justify-center gap-2 rounded-2xl border border-dashed border-[#b9cbb1] bg-[#f7fbf2] py-4 text-sm font-semibold text-[#5b765a]"><Upload size={17} /> Upload CNIC / skill proof <span className="text-xs text-[#9aa79d]">(optional for demo)</span></button>'
new = '<div className="mt-4 grid gap-3 sm:grid-cols-2"><label className="flex cursor-pointer items-center gap-3 rounded-2xl border border-dashed border-[#b9cbb1] bg-[#f7fbf2] p-4 text-sm font-semibold text-[#5b765a]"><Upload size={17} /><span>{form.diplomaProof ? form.diplomaProof.name : "Upload diploma proof *"}</span><input type="file" accept="image/*,.pdf" className="hidden" onChange={(e) => readProof("diplomaProof", e.target.files?.[0])} /></label><label className="flex cursor-pointer items-center gap-3 rounded-2xl border border-dashed border-[#b9cbb1] bg-[#f7fbf2] p-4 text-sm font-semibold text-[#5b765a]"><Upload size={17} /><span>{form.skillProof ? form.skillProof.name : "Upload skill proof *"}</span><input type="file" accept="image/*,.pdf" className="hidden" onChange={(e) => readProof("skillProof", e.target.files?.[0])} /></label></div>'
if old not in s: raise SystemExit('proof placeholder not found')
s = s.replace(old, new, 1)
s = s.replace('!form.experience || !form.bio || !form.consent', '!form.experience || !form.bio || !form.diplomaProof || !form.skillProof || !form.consent')
p.write_text(s)
